package ru.kstolu.app;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.android.controller.ActivityController;import java.io.*;import java.lang.reflect.*;import java.time.Duration;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w390dp-h844dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class FeaturesTest {
 private Context c;private ActivityController<MainActivity> main;private ActivityController<CookingActivity> cook;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();for(String name:new String[]{"settings","library","prices","cooking"})c.getSharedPreferences(name,0).edit().clear().commit();new File(c.getFilesDir(),"history.json").delete();ApiClient.clearSession();ApiClient.configureForTests(null,u->{throw new IOException("Unexpected network: "+u);});}
 @After public void end(){if(main!=null)main.pause().stop().destroy();if(cook!=null)cook.pause().stop().destroy();ApiClient.restoreTransport();}
 private JSONObject recipe()throws Exception{return new JSONObject("{\"status\":\"ok\",\"title\":\"Тосты с авокадо\",\"description\":\"Хрустящий хлеб, нежный сыр и спелый авокадо.\",\"meal_type\":\"breakfast\",\"servings\":2,\"prep_minutes\":5,\"cook_minutes\":10,\"ingredients\":[{\"name\":\"Хлеб\",\"amount\":80,\"unit\":\"g\",\"price\":null},{\"name\":\"Авокадо\",\"amount\":1,\"unit\":\"piece\",\"price\":null}],\"steps\":[{\"title\":\"Подготовьте продукты\",\"body\":\"Вымойте авокадо. Осторожно разрежьте вдоль, удалите косточку ложкой, снимите кожицу и нарежьте мякоть ломтиками толщиной 5 мм.\"},{\"title\":\"Подрумяньте хлеб\",\"body\":\"Поставьте сухую сковороду на средний огонь. Выложите хлеб в один слой. Прогревайте до лёгкой корочки, переверните и проверьте вторую сторону. При необходимости убавьте огонь.\",\"timer_seconds\":120,\"timer_hint\":\"Начните отсчёт после того, как положите хлеб на прогретую сковороду.\"},{\"title\":\"Соберите тосты\",\"body\":\"Переложите хлеб на тарелку, разложите ломтики авокадо. Подавайте сразу.\"}],\"warnings\":[],\"nutrition\":{\"source\":\"estimate\",\"kcal_per_serving\":320},\"image_prompt\":\"Open faced toast with visible green avocado slices on a plain plate, no extra toppings.\"}");}
 private JSONObject item()throws Exception{return new JSONObject().put("recipe",recipe()).put("currency","RUB");}
 private MainActivity open()throws Exception{main=Robolectric.buildActivity(MainActivity.class).setup();MainActivity a=main.get();invoke(a,"home");return a;}
 private Object invoke(Object a,String n,Object...args)throws Exception{for(Method m:a.getClass().getDeclaredMethods())if(m.getName().equals(n)){m.setAccessible(true);return m.invoke(a,args);}throw new NoSuchMethodException(n);}
 private void set(Object a,String n,Object value)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,value);}
 private TextView find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return(TextView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView t=find(g.getChildAt(i),text);if(t!=null)return t;}}return null;}
 private <T> T type(View v,Class<T> cls){if(cls.isInstance(v))return cls.cast(v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){T t=type(g.getChildAt(i),cls);if(t!=null)return t;}}return null;}
 private void shot(Activity a,String name,int w,int h)throws Exception{View root=a.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));root.layout(0,0,w,h);Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);root.draw(new Canvas(b));File dir=new File("build/outputs/review09");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private void dialogShot(AlertDialog dialog,String name)throws Exception{View root=dialog.getWindow().getDecorView();int width=358;root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(700,View.MeasureSpec.AT_MOST));int height=Math.max(1,Math.min(700,root.getMeasuredHeight()));root.layout(0,0,width,height);Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);root.draw(new Canvas(b));File dir=new File("build/outputs/review09");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private byte[] jpeg(){Bitmap b=Bitmap.createBitmap(160,120,Bitmap.Config.ARGB_8888);b.eraseColor(0xffb5c4a3);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,80,out);b.recycle();return out.toByteArray();}
 @Test public void fourPhotosAndPreferencesPersistWithoutNetwork()throws Exception{MainActivity a=open();ArrayList<byte[]> photos=new ArrayList<>();for(int i=0;i<4;i++)photos.add(jpeg());Field f=MainActivity.class.getDeclaredField("productPhotos");f.setAccessible(true);((List<byte[]>)f.get(a)).addAll(photos);set(a,"productPhoto",photos.get(0));invoke(a,"persistInputs");invoke(a,"home");View root=a.getWindow().getDecorView();assertNotNull(find(root,"Ваши продукты · 4 / 4"));find(root,"Без салатов").performClick();assertTrue(c.getSharedPreferences("settings",0).getStringSet("preferences",Set.of()).contains("no_salads"));shot(a,"01-home-four-photos",390,844);find(root,"Убрать 2").performClick();assertEquals(3,((List<?>)f.get(a)).size());main.pause().stop().destroy();main=null;a=open();assertEquals(3,((List<?>)f.get(a)).size());assertNotNull(find(a.getWindow().getDecorView(),"✓  Без салатов"));}
 @Test public void librarySearchFoldersAndRatingAreLocal()throws Exception{JSONObject one=item();Library.save(c,one);assertTrue(Library.addFolder(c,"Мои ужины"));assertFalse(Library.addFolder(c," мои УЖИНЫ "));Library.assign(c,one.getJSONObject("recipe"),Set.of("Мои ужины"));Library.rate(c,one.getJSONObject("recipe"),5);assertEquals(5,Library.rating(c,recipe()));assertTrue(Library.matches(recipe(),"тосты авокадо"));assertFalse(Library.matches(recipe(),"курица"));MainActivity a=open();invoke(a,"showHistory");assertNotNull(find(a.getWindow().getDecorView(),"Мои ужины"));shot(a,"02-library",390,844);EditText search=type(a.getWindow().getDecorView(),EditText.class);search.setText("курица");assertNotNull(find(a.getWindow().getDecorView(),"Ничего не найдено"));search.setText("Авокадо");assertNotNull(find(a.getWindow().getDecorView(),"Открыть рецепт"));invoke(a,"openRecipe",one,"history");invoke(a,"folderPicker",recipe());dialogShot(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog(),"11-folder-picker");}
 @Test public void manualPriceIsScaledDoesNotRewriteRecipe()throws Exception{JSONObject recipe=recipe(),ingredient=recipe.getJSONArray("ingredients").getJSONObject(0);assertNull(PriceBook.price(c,ingredient,"RUB"));PriceBook.save(c,ingredient,"RUB",1000,100);assertEquals("manual",PriceBook.price(c,ingredient,"RUB").getString("source"));assertNull(ingredient.optJSONObject("price"));assertNull(PriceBook.price(c,ingredient,"EUR"));MainActivity a=open();String cost=(String)invoke(a,"cost",recipe,1,"RUB");assertTrue(cost.contains("4"));assertTrue(cost.contains("неизвестные"));try{PriceBook.save(c,ingredient,"RUB",0,100);fail();}catch(IllegalArgumentException expected){}assertEquals(8.5,PriceBook.decimal("8,5"),.001);invoke(a,"openRecipe",new JSONObject().put("recipe",recipe).put("currency","RUB"),"choices");shot(a,"03-recipe-prices",390,844);invoke(a,"editPrice",ingredient,"RUB");assertNotNull(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog());dialogShot(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog(),"09-price-editor");}
 @Test public void readyPhotoReopensWithoutRegenerationAndCancelKeepsIt()throws Exception{MainActivity a=open();JSONObject item=item(),pending=new JSONObject().put("requestId",UUID.randomUUID()).put("snapshot",item).put("phase","ready");c.getSharedPreferences("settings",0).edit().putString("pendingImage",pending.toString()).commit();java.nio.file.Files.write(new File(c.getFilesDir(),"pending-image.jpg").toPath(),jpeg());invoke(a,"openRecipe",item,"choices");assertNotNull(find(a.getWindow().getDecorView(),"Посмотреть результат"));find(a.getWindow().getDecorView(),"Посмотреть результат").performClick();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(d.isShowing());dialogShot(d,"10-ready-preview");d.cancel();assertTrue(c.getSharedPreferences("settings",0).contains("pendingImage"));find(a.getWindow().getDecorView(),"Посмотреть результат").performClick();AlertDialog ready=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(ready.isShowing());Shadows.shadowOf(Looper.getMainLooper()).idle();ready.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertFalse(c.getSharedPreferences("settings",0).contains("pendingImage"));assertNotNull(find(a.getWindow().getDecorView(),"Фото сохранено"));find(a.getWindow().getDecorView(),"Фото сохранено").performClick();dialogShot(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog(),"13-saved-photo");assertEquals(1,Library.read(c).length());}
 @Test public void catalogKeepsAllCategoriesAndSortsLocally()throws Exception{MainActivity a=open();JSONArray rows=new JSONArray();for(int i=0;i<8;i++){JSONObject item=item();item.getJSONObject("recipe").put("title","Блюдо "+i).put("meal_type",i%2==0?"main":"soup");rows.put(item);}set(a,"choices",rows);invoke(a,"showChoices");assertNotNull(find(a.getWindow().getDecorView(),"Блюдо 7"));shot(a,"04-catalog",390,844);}
 private CookingActivity cooking()throws Exception{Intent i=new Intent(c,CookingActivity.class).putExtra("item",item().toString());cook=Robolectric.buildActivity(CookingActivity.class,i).setup();return cook.get();}
 @Test public void timerPauseRestoreAndRebootNeverAdvanceTwice()throws Exception{CookingState state=new CookingState();state.start(120,1000,2);assertEquals(120000,state.left(1000));state.pause(31000);assertEquals(90000,state.left(70000));state.start(90,70000,2);CookingState restored=CookingState.restore(state.json(),2);assertTrue(restored.expire(160000));assertEquals(1,restored.index);assertFalse(restored.expire(160001));CookingState reboot=CookingState.restore(state.json(),3);assertFalse(reboot.running);assertFalse(reboot.expire(999999));assertEquals(0,reboot.index);}
 @Test public void cookingManualTimerExpiresToNextAndRatingSaves()throws Exception{CookingActivity a=cooking();shot(a,"05-cooking-step",390,844);Field sf=CookingActivity.class.getDeclaredField("state");sf.setAccessible(true);CookingState state=(CookingState)sf.get(a);assertFalse(state.running);state.index=1;invoke(a,"render");assertNotNull(find(a.getWindow().getDecorView(),"02:00"));shot(a,"06-cooking-timer",390,844);find(a.getWindow().getDecorView(),"▷").performClick();assertTrue(state.running);state.deadline=SystemClock.elapsedRealtime()+100;Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(1));assertEquals(2,state.index);assertFalse(state.running);assertNotNull(find(a.getWindow().getDecorView(),"Соберите тосты"));state.index=3;invoke(a,"render");shot(a,"07-cooking-rating",390,844);RatingBar stars=type(a.getWindow().getDecorView(),RatingBar.class);stars.setRating(4);find(a.getWindow().getDecorView(),"Сохранить оценку").performClick();assertEquals(4,Library.rating(c,recipe()));assertEquals(1,Library.read(c).length());assertFalse(c.getSharedPreferences("cooking",0).contains("item"));cook.pause().stop().destroy();cook=null;assertFalse(c.getSharedPreferences("cooking",0).contains("item"));}
 @Test public void cookingRotationRestoresRunningTimerAndLandscapeFits()throws Exception{CookingActivity a=cooking();Field sf=CookingActivity.class.getDeclaredField("state");sf.setAccessible(true);CookingState state=(CookingState)sf.get(a);state.index=1;state.start(120,SystemClock.elapsedRealtime(),android.provider.Settings.Global.getInt(c.getContentResolver(),android.provider.Settings.Global.BOOT_COUNT,0));invoke(a,"persist");cook.pause().stop().destroy();cook=null;a=cooking();state=(CookingState)sf.get(a);assertEquals(1,state.index);assertTrue(state.running);shot(a,"08-cooking-landscape",844,390);}
 @Test public void horizontalTransitionMovesOneStepAndBoundaryKeepsTimer()throws Exception{CookingActivity a=cooking();Field sf=CookingActivity.class.getDeclaredField("state");sf.setAccessible(true);CookingState state=(CookingState)sf.get(a);state.start(60,SystemClock.elapsedRealtime(),0);invoke(a,"move",-1);assertTrue(state.running);assertEquals(0,state.index);state.pause(SystemClock.elapsedRealtime());state.remaining=0;invoke(a,"move",1);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(500));assertEquals(1,state.index);assertNotNull(find(a.getWindow().getDecorView(),"Подрумяньте хлеб"));}
 @Test public void timerEditorPausesSafelyAndDoesNotAutoStart()throws Exception{CookingActivity a=cooking();Field sf=CookingActivity.class.getDeclaredField("state");sf.setAccessible(true);CookingState state=(CookingState)sf.get(a);state.index=1;state.start(120,SystemClock.elapsedRealtime(),0);invoke(a,"render");invoke(a,"editTimer");assertFalse(state.running);AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();dialogShot(d,"12-timer-editor");EditText minutes=type(d.getWindow().getDecorView(),EditText.class);minutes.setText("1,5");assertEquals("1,5",minutes.getText().toString());Shadows.shadowOf(Looper.getMainLooper()).idle();d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertEquals(90000,state.remaining);assertFalse(state.running);assertEquals(1,state.index);}
 @Test public void fiftyVeryDetailedRecipesDoNotDisappearPastOldFourMiBLimit()throws Exception{JSONArray rows=new JSONArray();JSONObject recipe=recipe();JSONArray steps=new JSONArray();for(int j=0;j<20;j++)steps.put(new JSONObject().put("title","Подробный шаг "+j).put("body","а".repeat(2500)));recipe.put("steps",steps);for(int i=0;i<50;i++)rows.put(new JSONObject().put("recipe",new JSONObject(recipe.toString()).put("title","Подробный рецепт "+i)).put("currency","RUB"));Library.write(c,rows);assertTrue(new File(c.getFilesDir(),"history.json").length()>4*1024*1024);MainActivity a=open();invoke(a,"readHistory");Field f=MainActivity.class.getDeclaredField("history");f.setAccessible(true);assertEquals(50,((JSONArray)f.get(a)).length());assertEquals(50,Library.read(c).length());}
}
